#include <iostream>
using namespace std;

int solve(int n) {
    if (n == 0) return 1;
    if (n < 0) return 0;

    int dp[4] = {0}; // Use a circular buffer of size 4
    dp[0] = 1;
    for (int i = 1; i <= n; i++) {
        int current = dp[i % 4]; // Current value based on circular index
        dp[i % 4] = dp[(i - 1) % 4]; // dp[i] = dp[i - 1]
        if (i >= 2) dp[i % 4] += dp[(i - 2) % 4]; // dp[i] += dp[i - 2]
        if (i >= 3) dp[i % 4] += dp[(i - 3) % 4]; // dp[i] += dp[i - 3]
    }
    return dp[n % 4]; // Return the last computed value
}

int main() {
    while (true) {
        int n;
        cin >> n;
        if (n == 0) break;
        cout << solve(n) / 3650 + 1 << endl;
    }
    return 0;
}

